def load_into_cpu(self, model_path):
    request = storage_pb2.LoadModelRequest(
        model_path=model_path,
        target_device_type=storage_pb2.DeviceType.DEVICE_TYPE_CPU,
    )
    try:
        response = self.stub.LoadModelAsync(request)
    except grpc.RpcError as e:
        if e.code() == grpc.StatusCode.CANCELLED:
            logger.error(f"Model not loaded {e}")
            return False
        else:
            logger.error(f"Error: {e}")
            return False
    else:
        return response

async def LoadModelAsync(self, request, context):
    model_path = request.model_path
    if not model_path:
        logger.error("model_path is empty")
        context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
        return storage_pb2.LoadModelResponse()

    if not self.registration_required:
        model_size = self.storage.register_model_info(model_path)
        if model_size < 0:
            logger.error("RegisterModel failed")
            context.set_code(grpc.StatusCode.INTERNAL)
            return storage_pb2.LoadModelResponse()

    device_type = request.target_device_type
    if device_type == storage_pb2.DEVICE_TYPE_CPU:
        ret = self.storage.load_model_from_disk_async(model_path)
    elif device_type == storage_pb2.DEVICE_TYPE_GPU:
        replica_uuid = request.replica_uuid
        if not replica_uuid:
            logger.error("replica_uuid is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.LoadModelResponse()

        gpu_memory_handles = {
            device_uuid: [
                handle.cuda_ipc_handle for handle in handle_list.handles
            ]
            for device_uuid, handle_list in request.handles.items()
        }

        def create_mem_copy_chunk(chunk):
            mem_copy_chunk = MemCopyChunk()
            mem_copy_chunk.src_offset = chunk.src_offset
            mem_copy_chunk.size = chunk.size
            mem_copy_chunk.dst_offset = chunk.dst_offset
            mem_copy_chunk.handle_idx = chunk.handle_idx
            return mem_copy_chunk

        mem_copy_chunks = {
            device_uuid: [
                create_mem_copy_chunk(chunk) for chunk in chunk_list.chunks
            ]
            for device_uuid, chunk_list in request.chunks.items()
        }
        # logger.debug(
        #     f"LoadModelAsync: {model_path}, {replica_uuid}, "
        #     f"{gpu_memory_handles}, {mem_copy_chunks}"
        # )
        ret = self.storage.load_model_from_mem_async(
            model_path, replica_uuid, gpu_memory_handles, mem_copy_chunks
        )
    else:
        logger.error(f"Unsupported device type: {device_type}")
        context.set_code(grpc.StatusCode.UNIMPLEMENTED)
        return storage_pb2.LoadModelResponse()

    if ret != 0:
        logger.error("LoadModel failed")
        context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.LoadModelResponse()

    logger.info(
        f"LoadModel: success {model_path} with target {device_type}"
    )
    return storage_pb2.LoadModelResponse(model_path=model_path)

int CheckpointStore::LoadModelFromDisk(const std::string& model_path) {
  std::unique_lock<std::mutex> lock_info(model_info_mutex_);
  auto model = GetModelPtr(model_path);
  if (model == nullptr) {
    LOG(ERROR) << "Model " << model_path << " is not registered";
    return -1;
  }
  lock_info.unlock();

  // Allocate memory
  lock_info.lock();
  int remaining_size = model->AllocatePinnedMemory(memory_pool_);
  if (remaining_size < 0) {
    LOG(ERROR) << "Failed to allocate memory for model " << model_path;
    return -1;
  } else if (remaining_size > 0) {
    int mem_chunks_needed = remaining_size;
    std::vector<std::pair<std::string,
                          std::chrono::time_point<std::chrono::system_clock>>>
        model_last_access_time(model_last_access_time_.begin(),
                               model_last_access_time_.end());
    std::sort(model_last_access_time.begin(), model_last_access_time.end(),
              [](const auto& a, const auto& b) { return a.second < b.second; });
    for (const auto& [model_path, last_access_time] : model_last_access_time) {
      auto& model = model_map_[model_path];
      int freed_chunks =
          model->TryFreeHost();  // try to free memory, non-blocking
      LOG(INFO) << "Free " << freed_chunks << " chunks, remaining "
                << mem_chunks_needed;
      if (freed_chunks > 0) {
        LOG(INFO) << "Model " << model_path << " is freed from memory";
        mem_chunks_needed -= freed_chunks;
        if (mem_chunks_needed <= 0) {
          break;
        }
      }
    }
    if (mem_chunks_needed > 0) {
      LOG(ERROR) << "Failed to free enough memory for model " << model_path;
      return -1;
    }
    ssize_t remaining_size = model->AllocatePinnedMemory(memory_pool_);
    if (remaining_size < 0) {
      LOG(ERROR) << "Failed to allocate memory for model " << model_path;
      return -1;
    }
  }
  model_last_access_time_[model_path] = std::chrono::system_clock::now();
  lock_info.unlock();

  int ret = model->ToHost(num_thread_);

  if (ret != 0) {
    LOG(ERROR) << "Failed to load model " << model_path << " to host";
    if (model->FreeHost() != 0) {
      LOG(ERROR) << "Failed to free memory for model " << model_path;
    }
    return ret;
  }

  return ret;
}

int CheckpointStore::LoadModelFromDiskAsync(const std::string& model_path) {
  std::unique_lock<std::mutex> lock_info(model_info_mutex_);
  async_tasks_.emplace(std::async(std::launch::async, [this, model_path]() {
    return LoadModelFromDisk(model_path);
  }));

  return 0;

bool error = false;
for (auto& future : futures) {
  int ret = future.get();
  if (ret != 0) {
    LOG(ERROR) << "Error reading from disk, ret " << ret;
    error = true;
  }
}

// close file
for (int fd : file_descriptors) {
  close(fd);
}

lock.lock();
if (error) {
  state_ = MemoryState::INTERRUPTED;
  // Deal with gpu replicas
  for (auto& [replica_uuid, gpu_replica] : gpu_replicas_) {
    if (gpu_replica->state_ == MemoryState::LOADING) {
      gpu_replica->state_ = MemoryState::CANCELLED;
      gpu_replica->cv_.notify_all();
    }
    // wait for gpu replicas to finish
    gpu_replica->cv_.wait(lock, [&gpu_replica] {
      return gpu_replica->state_ == MemoryState::LOADED ||
             gpu_replica->state_ == MemoryState::INTERRUPTED;
    });
    // Note: gpu replicas will be handled by the caller
  }
  // release pinned memory
  pinned_mem_.reset();
  state_ = MemoryState::UNALLOCATED;

  return -1;
}

state_ = MemoryState::LOADED;
LOG(INFO) << "Finished loading model " << model_path_ << " from disk";

return 0;
